"""Arena Studio -> APK using the GenAPK.py flow (generated by arena_exe_builder).

GenAPK.py (next to this file) is the unmodified original. This runner calls its functions in its own order:
    create project structure -> initialize_buildozer -> update_buildozer_spec -> build_apk
and works around four things that stop the original from building a game:
  1. Its main.py template is a Kivy WebView app (Kivy has no webview widget), so the staged Arena main.py is kept.
  2. initialize_buildozer() changes into the project folder, after which update_buildozer_spec() looks for
     <project>/<project>/buildozer.spec and never finds it, so the project is addressed as "." here.
  3. The default Buildozer spec only requires python3 + kivy, so the Arena settings (buildozer.arena.spec,
     written by the compiler) are applied on top: pygame, numpy, orientation, Android API/NDK, icon, ...
  4. Its run_command() never read stderr or checked exit codes, so a failed build looked like a success.
Usage:  python3 genapk_arena.py            (full build)
        python3 genapk_arena.py --no-build (create and patch buildozer.spec only)
"""
import glob
import os
import re
import subprocess
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
os.chdir(HERE)
sys.path.insert(0, HERE)

import GenAPK as genapk  # the unmodified original

OVERRIDES = os.path.join(HERE, "buildozer.arena.spec")
SPEC = os.path.join(HERE, "buildozer.spec")


def run_command(command):
    """Replacement for GenAPK.run_command: merged output, live printing, real exit code."""
    env = dict(os.environ)
    env["PYTHONUNBUFFERED"] = "1"
    env.setdefault("PIP_BREAK_SYSTEM_PACKAGES", "1")
    proc = subprocess.Popen(command, shell=True, stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                            stderr=subprocess.STDOUT, env=env)
    try:
        # Buildozer asks "running as root, continue? [y/n]" when started as root (Colab, some WSL setups).
        proc.stdin.write(b"y\ny\ny\n")
        proc.stdin.close()
    except OSError:
        pass
    for line in proc.stdout:
        sys.stdout.write(line.decode("utf-8", "replace"))
        sys.stdout.flush()
    code = proc.wait()
    if code:
        print("\nGenAPK step failed (exit code %d): %s" % (code, command))
        raise SystemExit(code)


genapk.run_command = run_command


def read_overrides(path):
    """[(section, key, value), ...] from the compiler-written buildozer.arena.spec."""
    found = []
    section = None
    if not os.path.isfile(path):
        return found
    with open(path, encoding="utf-8") as handle:
        for raw in handle:
            line = raw.strip()
            if not line or line.startswith("#"):
                continue
            if line.startswith("[") and line.endswith("]"):
                section = line[1:-1]
                continue
            if "=" in line and section:
                key, value = line.split("=", 1)
                found.append((section, key.strip(), value.strip()))
    return found


def set_key(lines, section, key, value):
    """Set `key = value` inside [section], replacing the live or commented default line."""
    start = None
    for index, text in enumerate(lines):
        if text.strip() == "[%s]" % section:
            start = index + 1
            break
    if start is None:
        lines.extend(["\n", "[%s]\n" % section])
        start = len(lines)
    end = len(lines)
    for index in range(start, len(lines)):
        stripped = lines[index].strip()
        if stripped.startswith("[") and stripped.endswith("]"):
            end = index
            break
    pattern = re.compile(r"^\s*#?\s*" + re.escape(key) + r"\s*=")
    hits = [i for i in range(start, end) if pattern.match(lines[i])]
    live = [i for i in hits if not lines[i].lstrip().startswith("#")]
    new = "%s = %s\n" % (key, value)
    if hits:
        target = (live or hits)[0]
        lines[target] = new
        for extra in reversed(live[1:]):  # never leave two live definitions of one key
            del lines[extra]
    else:
        lines.insert(end, new)


def apply_overrides():
    values = read_overrides(OVERRIDES)
    if not values:
        print("No buildozer.arena.spec found; the default GenAPK spec is used as is.")
        return
    with open(SPEC, encoding="utf-8") as handle:
        lines = handle.readlines()
    if lines and not lines[-1].endswith("\n"):
        lines[-1] += "\n"
    for section, key, value in values:
        set_key(lines, section, key, value)
    with open(SPEC, "w", encoding="utf-8", newline="\n") as handle:
        handle.writelines(lines)
    print("Applied %d Arena settings to buildozer.spec (requirements, orientation, API/NDK, icon, ...)." % len(values))


def main():
    if not os.path.isfile(os.path.join(HERE, "main.py")):
        print("main.py is missing from the project folder; stage the project with the compiler first.")
        return 2
    app = {key: value for section, key, value in read_overrides(OVERRIDES) if section == "app"}
    title = app.get("title", "Arena Studio")
    package_name = app.get("package.name", "arenastudio")
    package_domain = app.get("package.domain", "org.arenastudio")

    print("=== GenAPK 1/4: project structure (Arena main.py kept; GenAPK's WebView template skipped) ===")
    print("Project folder: " + HERE)
    print("=== GenAPK 2/4: initialize Buildozer ===")
    genapk.initialize_buildozer(".")
    print("=== GenAPK 3/4: update buildozer.spec ===")
    genapk.update_buildozer_spec(".", title, package_name, package_domain)
    apply_overrides()
    if "--no-build" in sys.argv:
        print("--no-build: stopping before the APK build.")
        return 0
    print("=== GenAPK 4/4: build APK (first build downloads several GB and takes 20-60 minutes) ===")
    genapk.build_apk()
    apks = sorted(glob.glob(os.path.join(HERE, "bin", "*.apk")), key=os.path.getmtime)
    if not apks:
        print("GenAPK finished, but no APK was found in the bin folder.")
        return 1
    print("APK ready: " + apks[-1])
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
